{
 "paper_title": "Some Methods for Classification and Analysis of Multivariate Observations",
 "authors_year": "J. MacQueen, 1967",
 "research_question": "How can an N-dimensional population be partitioned into k sets on the basis of a sample using a computationally feasible process (k-means), and what is the asymptotic behavior of this process?",
 "context": "The work originates from problems in optimal classification and optimal information structures where the objective is to partition a population to minimize within-class variance (expected squared error loss).",
 "methods": [
  "Mathematical and asymptotic analysis using martingale theory and measure theory",
  "Computer experiments on real and artificial datasets using the k-means procedure with coarsening and refining parameters C and R",
  "Extension of the k-means concept to general compact metric spaces using centroids of order r"
 ],
 "main_findings": [
  "The sequence of random variables W(x^n) associated with sample k-means converges almost surely to V(x) for some unbiased k-point x.",
  "The k-means procedure is computationally economical and feasible for large samples on a digital computer.",
  "Practical applications of k-means include similarity grouping/clustering, relevant classification for prediction, approximating general distributions with normal mixtures, and a scrambled dimension test for independence."
 ],
 "assumptions": [
  "The probability measure p is absolutely continuous with respect to Lebesgue measure on EN.",
  "p(R) = 1 for a closed and bounded convex set R subset of EN, and p(A) > 0 for every open set A subset of R."
 ],
 "limitations_explicit": [
  "In general, the k-means procedure will not necessarily converge to an optimal partition.",
  "The convergence may oscillate slowly or depend on the initial starting points or random ordering of the sample points."
 ],
 "potential_open_questions": [
  {
   "question": "Can the k-means process be proven to avoid indefinitely slow oscillation around the center in all cases where unbiased k-points share the same value of W?",
   "why_unresolved": "Theorem 1 establishes almost sure convergence to the set of unbiased k-points but does not entirely eliminate the possibility of slow indefinite oscillation around the center.",
   "evidence": "Theorem 1 provides for a.s. convergence, but the text notes that theorem 1 does not quite permit us to eliminate the interesting possibility that the two means oscillate slowly but indefinitely around the center.",
   "sections": [
    "2.3"
   ]
  },
  {
   "question": "What is the exact statistical power of the proposed scrambled dimension test for independence across various multidimensional distributions?",
   "why_unresolved": "Lack of available computer programs to perform large numbers of scrambled samples using punched cards at the time of the study prevented extensive empirical testing.",
   "evidence": "A computer program was not available to do the scrambling, and its being inconvenient to set up large numbers of scrambled samples using punched cards, further testing of this method was not undertaken.",
   "sections": [
    "3.4"
   ]
  }
 ],
 "candidate_hypotheses": [
  {
   "hypothesis": "For fixed marginal distributions, the within-class variance for the optimal partition is maximal when the joint distribution is actually the product of the marginals.",
   "rationale": "Intuition and inspection of simple examples suggest that destroying dependence via scrambling increases within-class variance.",
   "evidence": "On the encouraging side is the related conjecture, that for fixed marginal distributions, the within-class variance for the optimal partition as defined in section 1 is maximal when the joint distribution is actually the product of the marginals.",
   "sections": [
    "3.4"
   ]
  },
  {
   "hypothesis": "Under independent sampling in general compact metric spaces, the sum of integrals defining the sample k-centroids converges almost surely to limits in the class of unbiased k-centroids.",
   "rationale": "Analogy to the Euclidean case and uniform boundedness of random variables in compact spaces via Parzen's theorem.",
   "evidence": "It would seem reasonable to suppose that the obvious extension of theorem 1 would hold. That is, under independent sampling, sum of integrals of p^r will converge a.s., and convergent subsequences will have limits in the class of unbiased k-points.",
   "sections": [
    "4"
   ]
  }
 ]
}

